create function public.purchase_economy_item(
  p_request_id uuid, p_item_kind text, p_catalog_id text,
  p_protocol_version integer, p_client_build integer
) returns jsonb language plpgsql security definer set search_path = '' as $$
declare keeper uuid := auth.uid(); started jsonb; response jsonb; rules jsonb;
  wallet public.player_wallets%rowtype; item_id uuid; version bigint;
  price integer; currency text; outcome text := 'purchased';
begin
  perform private.assert_economy_client(p_protocol_version, p_client_build);
  if p_item_kind is null or p_item_kind not in ('furniture', 'relic') or p_catalog_id is null
    or p_catalog_id !~ '^[A-Za-z0-9_.-]{1,100}$' then raise exception 'economy_shop_item_unknown'; end if;
  rules := private.economy_shop_catalog()->p_item_kind->p_catalog_id;
  if rules is null then raise exception 'economy_shop_item_unknown'; end if;
  price := (rules->>'price')::integer; currency := rules->>'currency';
  perform pg_advisory_xact_lock(hashtextextended(keeper::text, 0));
  started := private.begin_economy_mutation(p_request_id, 'shop.purchase_item',
    p_protocol_version, p_client_build,
    jsonb_build_object('kind', p_item_kind, 'catalog_id', p_catalog_id), 20, 60);
  if (started->>'replayed')::boolean then
    if started->>'status' <> 'succeeded' then raise exception 'economy_request_state_invalid'; end if;
    return started->'response';
  end if;
  select server_revision into version from public.player_economy_authority where user_id = keeper for update;
  select * into wallet from public.player_wallets where user_id = keeper for update;
  if not found then raise exception 'economy_wallet_missing'; end if;
  if (rules->>'unique_while_owned')::boolean then
    select id into item_id from public.player_item_instances where owner_id = keeper
      and item_kind = p_item_kind and catalog_id = p_catalog_id and state <> 'consumed'
      order by acquired_at, id limit 1;
    if found then outcome := 'already_owned'; end if;
  end if;
  if outcome = 'purchased' and ((currency = 'coins' and wallet.coins < price)
    or (currency = 'gems' and wallet.gems < price)) then outcome := 'insufficient_funds'; end if;
  if outcome = 'purchased' then
    update public.player_wallets set coins = coins - case when currency = 'coins' then price else 0 end,
      gems = gems - case when currency = 'gems' then price else 0 end,
      revision = revision + 1, updated_at = clock_timestamp()
      where user_id = keeper returning * into wallet;
    insert into public.player_item_instances(owner_id, item_kind, catalog_id, tradeable, source_type, source_reference)
      values(keeper, p_item_kind, p_catalog_id, (rules->>'tradeable')::boolean,
        'shop', 'item_shop_v1') returning id into item_id;
    perform private.append_economy_ledger_entry(keeper, p_request_id, currency, currency,
      'debit', 'shop', -price, case when currency = 'coins' then wallet.coins else wallet.gems end,
      'item_shop_v1', jsonb_build_object('catalog_id', p_catalog_id, 'item_kind', p_item_kind, 'price', price));
    perform private.append_economy_ledger_entry(keeper, p_request_id, 'item', p_catalog_id,
      'grant', 'shop', 1, null, 'item_shop_v1', jsonb_build_object('instance_id', item_id, 'item_kind', p_item_kind));
    update public.player_economy_authority set server_revision = server_revision + 1
      where user_id = keeper returning server_revision into version;
  end if;
  response := jsonb_build_object('outcome', outcome, 'item_kind', p_item_kind,
    'catalog_id', p_catalog_id, 'instance_id', item_id, 'currency', currency, 'price', price,
    'coins', wallet.coins, 'gems', wallet.gems, 'wallet_revision', wallet.revision, 'server_revision', version);
  perform private.complete_economy_mutation(keeper, p_request_id, response);
  return response;
end;
$$;

revoke all on function private.economy_shop_catalog() from public, anon, authenticated;
revoke all on function public.purchase_economy_item(uuid,text,text,integer,integer) from public, anon;
grant execute on function public.purchase_economy_item(uuid,text,text,integer,integer) to authenticated;
